"""Build and serve a local, printable Arabic engineering audit. No model calls."""
import argparse
import hashlib
import json
import statistics
from http.server import SimpleHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlsplit

ROOT=Path(__file__).resolve().parent
OUT=ROOT/'fidelity-review'
NAMES={'front':'وجه أمامي','side':'وجه جانبي','full':'شخصية مرسومة كاملة','animal':'قطة','object':'فنجان'}
STYLES={'ink':'حبر خطي','minimal':'مختصر','pencil-light':'رصاص خفيف'}


def clock(seconds):
    seconds=round(seconds)
    return f'{seconds//60}:{seconds%60:02}'


def build():
    rows=json.loads((OUT/'audit.json').read_text(encoding='utf-8'))
    assert len(rows)==15 and all('exportAudit' in r for r in rows),'Run evaluate, export, then verify first.'
    for r in rows:
        raw=(ROOT/'comparison-review'/f"{r['key']}-flux.png").read_bytes()
        assert hashlib.sha256(raw).hexdigest()==r['sourceSHA256']
        (OUT/f"{r['key']}-flux.png").write_bytes(raw)
    def median(name,group='score'):return round(statistics.median(r[group][name] for r in rows),2)
    table=''.join(f'''<tr><th scope="row">{NAMES[r['key'].split('-')[0]]}<small>{STYLES[r['key'].split('-',1)[1]]}</small></th><td>{r['viaPrecise']['inkIoU']}%</td><td>{r['score']['baselineCenterline']['inkIoU']}%</td><td class="good">{r['score']['inkIoU']}%</td><td>{r['exportAudit']['inkIoU']}%</td><td>{r['score']['inkRecall']}%</td><td>{r['count']:,}</td><td dir="ltr">{clock(r['oldMotion']['seconds'])} / {clock(r['motion']['seconds'])}</td><td><a href="{r['key']}.svg" download>SVG</a></td></tr>''' for r in rows)
    html=f'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تدقيق المطابقة | من FLUX إلى القلم</title><link rel="stylesheet" href="report.css"><script src="report.js" type="module"></script></head><body>
<a class="skip" href="#content">انتقل إلى التقرير</a><header class="top"><strong>مسار / مختبر المطابقة</strong><nav><a href="http://127.0.0.1:8770/">افتح التطبيق</a><button id="print">طباعة التقرير</button></nav></header><main id="content">
<section class="hero"><div><p class="eyebrow">تدقيق هندسي محلي · 27 أكتوبر 2026</p><h1>من صورة النموذج<br>إلى أثر القلم الحقيقي.</h1><p class="lead">فحص السلسلة كاملة، وتحديد مواضع فقد الحبر، ثم إعادة بناء المسارات بحسب سماكة القلم. المرجع هو خرج FLUX الخام المحفوظ، وليس لقطة معاينة محسّنة.</p></div><aside class="verdict"><span>الحكم</span><h2>تحسّن مُقاس،<br>ولم نصل إلى تطابق كامل.</h2><p>كل الحالات الخمس عشرة تحسنت في قناع الحبر مقارنة بالمسار عبر Lineart. الفروق الرمادية والتفاصيل الأصغر من أثر القلم ما زالت تحدّ المطابقة. التعبئات ترفع زمن التنفيذ.</p></aside></section>
<section class="stats" aria-label="خلاصة القياس"><article><span>وسيط تطابق الحبر الجديد</span><strong>{median('inkIoU')}%</strong><small>IoU · 15 رسمًا</small></article><article><span>المسار المقارن عبر Lineart</span><strong>{median('inkIoU','viaPrecise')}%</strong><small>القلم والقياس والمرجع نفسهما</small></article><article><span>وسيط الحبر المرجعي المستعاد</span><strong>{median('inkRecall')}%</strong><small>الاسترجاع، وليس تقييم هوية الوجه</small></article><article><span>خطأ الدرجات الرمادية</span><strong>{median('grayErrorInkRegion')}%</strong><small>داخل اتحاد مناطق الحبر · الأقل أفضل</small></article></section>
<section class="notice"><strong>ماذا تعني هذه النسب؟</strong><p>نقيس تداخل الحبر الأسود المستهدف مع أثر قلم ثابت القطر بعد إعادة رسم SVG. لا تعني النسبة مطابقة الصورة الملونة أو تشابه الشخص أو نجاح ذراع حقيقي. النطاق الفعلي للحالات: {min(r['score']['inkIoU'] for r in rows)}–{max(r['score']['inkIoU'] for r in rows)}%. أُعيد تدقيق ملفات SVG المحفوظة نفسها؛ قد تختلف أعشار النسبة عن الخطة الداخلية بسبب تقريب الإحداثيات.</p></section>
<section><div class="section-head"><div><span class="eyebrow">01 / أين كان الفقد؟</span><h2>ثلاث مشكلات متراكبة.</h2></div></div><div class="three"><article class="card"><b>01</b><h3>تغيير المرجع قبل التتبع</h3><p>اعتماد نتيجة FLUX كان يعيدها إلى التجهيز الرمادي وتخفيف الملمس، ثم يفرض Lineart. يمكن أن تتغير العينان والملامح قبل بناء أي مسار.</p><p class="fix">الإصلاح: اعتماد الخام مباشرة، مع إخراج Lineart من المنصة المعتمدة.</p></article><article class="card"><b>02</b><h3>اختزال مساحة إلى خط</h3><p>الترقيق يحفظ الهيكل المركزي لكنه يفقد عرض الحاجب والرموش والتعبئات السوداء. النقاط المنفردة التي لا تملك جيرانًا كانت قد تضيع من الرسم البياني.</p><p class="fix">الإصلاح: حفظ النقاط وإضافة تمريرات داخل مساحات الحبر.</p></article><article class="card"><b>03</b><h3>فصل القلم عن الهندسة</h3><p>قطر القلم كان يغير المظهر المعروض، بينما خطة النسخ المبنية على البكسلات لا تعاد وفق القياس على الورقة. مسار صحيح بكسليًا قد يرسم حبرًا زائدًا أو ناقصًا.</p><p class="fix">الإصلاح: تخطيط بالمليمتر، وهوامش تشمل أثر القلم.</p></article></div></section>
<section class="method"><div class="section-head"><div><span class="eyebrow">02 / السلسلة المصححة</span><h2>المرجع ثابت، والقياس يكشف الفارق.</h2></div></div><ol class="pipeline"><li><strong>خرج FLUX خام</strong><span>اعتماد صريح دون تنقية أو إعادة استدلال.</span></li><li><strong>قناع حبر + قياس ورقة</strong><span>عتبة Otsu أو عتبة يدوية، وقطر قلم بالمليمتر.</span></li><li><strong>تتبع وتعبئة</strong><span>خطوط مركزية، نقاط محفوظة، وحلقات داخل الحبر.</span></li><li><strong>تدقيق ثم تصدير</strong><span>إعادة رسم ثابتة السماكة وخريطة فقد وزيادة.</span></li></ol>
<div class="two"><article><h3>كيف تُحسب التمريرات؟</h3><p>OpenCV يحسب بُعد كل موضع حبر عن أقرب خلفية بيضاء بواسطة Distance Transform. نُنشئ حدودًا داخلية متدرجة بحسب نصف قطر القلم، ثم نحسّن الإحداثيات دون البكسل. نصل الحلقات فقط إن كان أثر القلم على الوصلة داخل منطقة آمنة؛ لا وصلة تعبر فراغ العين أو ثقوب الأشكال.</p><p>التخطيط يستخدم تكبيرًا داخليًا حتى 8× وبحد 40 مليون بكسل، دون تغيير الصورة الأصلية. يُحذف مسار مركزي مكرر فقط إذا غطّته التعبئة بالكامل. إذا خفّضت التعبئة درجة IoU نرجع إلى الخطوط المركزية المحفوظة.</p></article><article><h3>كيف نمنع النتيجة المضللة؟</h3><p>CairoSVG يعيد رسم الهندسة نفسها بقلم ثابت ونهايات ووصلات مستديرة. التدقيق يشمل الحبر المتجاوز إطار الصورة. نستهدف قناع الحبر الناتج من العتبة ونقيس خطأ الرمادي عند دقة الصورة الأصلية داخل اتحاد مناطق الحبر، دون اختراع درجات حواف بإعادة تكبير المرجع. لا تُحتسب الخلفية البيضاء لرفع نسبة المطابقة شكليًا.</p><p>أي استبعاد يدوي أو تغيير للعتبة أو القلم يُبطل القياس القديم. إعادة الترتيب وعكس اتجاه المسار لا تغير هندسته؛ تبقى حركات الانتقال دون حبر. لا تعبئات SVG مصطنعة ولا صورة مضمنة بدل مسارات.</p></article></div></section>
<section class="review"><div class="section-head"><div><span class="eyebrow">03 / راجع الصورة بنفسك</span><h2>الخام، والمسار المقارن، وإعادة الرسم.</h2></div><div class="filters"><label>العينة<select id="subject"><option value="front">وجه أمامي</option><option value="side">وجه جانبي</option><option value="full">شخصية مرسومة كاملة</option><option value="animal">قطة</option><option value="object">فنجان</option></select></label><label>أسلوب FLUX<select id="style"><option value="ink">حبر خطي</option><option value="minimal">مختصر</option><option value="pencil-light">رصاص خفيف</option></select></label></div></div><p id="caseSummary"></p><div class="three pictures"><figure><figcaption>خرج FLUX الخام</figcaption><a id="rawLink"><img id="raw" alt="خرج النموذج الخام"></a></figure><figure><figcaption>عبر Lineart + خط مركزي</figcaption><a id="oldLink"><img id="old" alt="الرسم المقارن بعد تحويله لمسارات"></a></figure><figure><figcaption>المسارات الجديدة · قلم 0.2 مم</figcaption><a id="newLink"><img id="new" alt="إعادة الرسم من المسارات الجديدة"></a></figure></div><details><summary>قناع الحبر وخريطة الفروقات · أحمر مفقود، أزرق زائد</summary><div class="two pictures"><figure><figcaption>القناع المرجعي بعد العتبة</figcaption><a id="targetLink"><img id="target" alt="قناع الحبر المرجعي"></a></figure><figure><figcaption>المطابقة والفقد والزيادة</figcaption><a id="differenceLink"><img id="difference" alt="خريطة الفروقات"></a></figure></div></details><p class="caption">انقر الصورة لفتحها بالحجم الكامل. الشخصية الكاملة مرسومة أصلًا؛ ليست اختبار جسم بشري فوتوغرافي. العينتان الحيوانية والغرض من صور عامة، والوجهان من عيناتك السابقة.</p></section>
<section><div class="section-head"><div><span class="eyebrow">04 / جميع الحالات</span><h2>القياس الكامل، بما فيه ثمن المطابقة.</h2></div><a href="audit.json" download>بيانات القياس JSON</a></div><p>الإعداد المشترك: A4 عمودي، هامش 15 مم، قلم 0.2 مم، رسم 30 مم/ث، انتقال 80 مم/ث، ورفع وخفض 0.4 ثانية لكل ضربة. لا حذف زمني أو استبعاد لأجزاء قصيرة. زاد الزمن لأننا نحافظ على نقاط وتعبئات فعلية.</p><div class="table-wrap" tabindex="0" role="region" aria-label="نتائج خمس عشرة حالة"><table><thead><tr><th>العينة / الأسلوب</th><th>عبر Lineart</th><th>مركزي مباشر*</th><th>الخطة الجديدة</th><th>SVG المحفوظ</th><th>استرجاع الحبر</th><th>ضربات جديدة</th><th>الزمن: المقارن / الجديد</th><th>ملف</th></tr></thead><tbody>{table}</tbody></table></div><p class="caption">* خط مركزي مباشر مع حفظ العلامات المنفردة، قبل إضافة التعبئة. الدرجة IoU في أعمدة المطابقة. الخطوط المقارنة محفوظة من الاختبار السابق لـ FLUX ثم Lineart؛ أُعيد قياسها مقابل الخام بالقلم والمقياس الجديدين، دون إعادة تشغيل النموذج أو محاكاة خطوة التجهيز القديمة.</p></section>
<section class="two"><article class="card"><span class="eyebrow">05 / ما لم يتحقق بعد</span><h2>حدود فعلية يجب أن تبقى ظاهرة.</h2><p>قلم أسود ثابت لا يطابق الألوان أو التدرجات الرمادية تمامًا. وقد يتجاوز قطره مساحة رمش أو نقطة صغيرة؛ تحسين البرومبت أو استخدام قلم أدق وحجم رسم أكبر يساعد، ولا يضمن تطابقًا كاملًا.</p><p>القناع الثنائي نفسه يفقد درجات رمادية خفيفة. لهذا تظهر صورة الخام بجانب النتيجة ويُعرض خطأ الرمادي مستقلاً. لم نختبر يدًا فعلية؛ الضغط والحبر والورق والانزلاق والتسارع والاهتزاز غير ممثلة في التقدير.</p><p>حدود التعقيد 6000 مسار و400 ألف نقطة و64 مستوى تعبئة. إذا تجاوزتها الصورة يتوقف التخطيط برسالة واضحة، دون قص التفاصيل بصمت.</p></article><article class="card"><span class="eyebrow">06 / الاستخدام الآن</span><h2>اعتمد الرسم، ثم افحص أثره.</h2><ol><li>ولّد رسمًا خطيًا بلا ظلال في FLUX وراجع العينين والملامح.</li><li>اختر «مراجعة الصورة قبل الاعتماد»، ثم «اعتماد الصورة وتحديد مسار القلم». تنتقل النسخة المعروضة نفسها دون معالجة وسيطة.</li><li>استخدم وضع «مطابقة الحبر»، وحدد الورقة وقطر القلم الحقيقي.</li><li>راجع الخام والقناع وإعادة الرسم والفروقات؛ بعد الحذف اليدوي أعد القياس.</li><li>صدّر SVG أو JSON. للمسار الأسرع اختر الخط المركزي، مع قبول فقد التعبئات.</li></ol><p>تحديث اعتماد المنصة: FLUX هو نموذج الصور المعتمد، وأُخرج Lineart من الواجهة والخادم. المقارنة عبر Lineart في هذا التقرير توثيق للاختبار التاريخي.</p></article></section>
<section class="method"><h2>المكتبات، المعادلات، والتحقق</h2><div class="two"><article><h3>التنفيذ المستخدم</h3><p>OpenCV contrib 4.10: Otsu، thinning، connected components، distanceTransform، findContours وSobel. Pillow لفك الصورة والشفافية، NumPy للحسابات، CairoSVG للرسم المستقل. JavaScript لهندسة الورقة وترتيب الأطراف والمحاكاة وتصدير SVG/JSON. لا نموذج توليدي جديد داخل استخراج المسارات.</p><p>الملفات: faithful_paths.py وpath_fidelity.py، وربط server.py وapp.js، مع Workflow للاعتماد وgeometry.js للهندسة. لم تُغيّر محركات التطبيقات القديمة المشتركة.</p></article><article><h3>تعريفات قابلة للمراجعة</h3><p dir="ltr">IoU = |target ∩ pen| / |target ∪ pen|<br>Recall = matched ink / target ink<br>Precision = matched ink / drawn ink<br>Time = ink mm / 30 + travel mm / 80 + strokes × 0.4</p><p>زمن الرسم تقدير للحركة والرفع، وليس زمن المعالجة أو قياس جهاز فعلي. هوامش الورقة تشمل نصف سماكة القلم وخلايا البكسل الخارجية. تحققنا من ملفات SVG الخمسة عشر، واتساق الزمن، وبصمات الصور الأصلية. 38 اختبارًا آليًا ناجحًا، إضافة إلى فحص HTTP: حفظ الثقوب والنقاط، اختلاف قطر القلم، المدخلات غير الصالحة، اعتماد الخام، وإبطال النتائج التابعة. اختبارات المتصفح: المسار المباشر، إبطال القياس بعد الحذف، وإعادة التدقيق.</p></article></div><p class="caption">مراجع المنهج: <a href="https://docs.opencv.org/4.x/d7/d1b/group__imgproc__misc.html">OpenCV: distanceTransform والعتبات</a> · <a href="https://docs.opencv.org/4.x/d9/d61/tutorial_py_morphological_ops.html">OpenCV: العمليات المورفولوجية</a>. نسب النتائج تخص العينات والإعدادات المبيّنة، ولا تعمم على كل الصور.</p></section>
<footer>تقرير محلي قابل للطباعة · لا رفع سحابي ولا نشر عام · <a href="http://127.0.0.1:8770/">العودة إلى مساحة العمل</a></footer></main></body></html>'''
    (OUT/'index.html').write_text(html,encoding='utf-8')
    for filename in ['report.css','report.js']:(OUT/filename).write_bytes((ROOT/('fidelity-'+filename)).read_bytes())
    return rows


class Handler(SimpleHTTPRequestHandler):
    def __init__(self,*args,**kwargs):super().__init__(*args,directory=str(OUT),**kwargs)
    def log_message(self,*args):pass
    def do_GET(self):
        if self.headers.get('Host') not in {f'127.0.0.1:{self.server.server_port}',f'localhost:{self.server.server_port}'}:self.send_error(403);return
        name=urlsplit(self.path).path.removeprefix('/') or 'index.html'
        if '/' in name or name.startswith('.') or not (OUT/name).is_file():self.send_error(404);return
        super().do_GET()
    def end_headers(self):
        self.send_header('Cache-Control','no-store');self.send_header('X-Content-Type-Options','nosniff');super().end_headers()


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--port',type=int,default=8773);args=parser.parse_args()
    build();print(f'Fidelity audit: http://127.0.0.1:{args.port}/',flush=True)
    ThreadingHTTPServer(('127.0.0.1',args.port),Handler).serve_forever()
